<script lang="ts">
import { tick } from 'svelte';
import type { ApexConfig, ApexLocale, ApexValidationErrors } from '../../../core/src/apex/mod.ts';
import { availableDate, formatInquiry, formatUSD, groupPrice, initialInquiry, mexicoToday, validateInquiry, whatsappUrl } from '../../../core/src/apex/mod.ts';
import type { createApexStore } from '../../../state/src/stores/apex.svelte.ts';
import { useResolver } from './url.ts';
let { config, locale, store, experienceId='la-marquesa',compact=false }: {config:ApexConfig;locale:ApexLocale;store:ReturnType<typeof createApexStore>;experienceId?:string;compact?:boolean}=$props();
const resolve = useResolver();
let inquiry=$state(initialInquiry());
$effect(()=>{inquiry=initialInquiry(experienceId);errors={};reviewed='';special=false;});
let errors=$state<ApexValidationErrors>({});
let special=$state(false);
let reviewed=$state('');
let feedback=$state('');
let summaryElement=$state<HTMLDivElement>();
let today=mexicoToday();
let month=$state(new Date(`${today.slice(0,7)}-01T12:00:00Z`));
let monthKey=$derived(`${month.getUTCFullYear()}-${String(month.getUTCMonth()+1).padStart(2,'0')}`);
let monthLabel=$derived(new Intl.DateTimeFormat(locale==='es'?'es-MX':'en-US',{month:'long',year:'numeric',timeZone:'UTC'}).format(month));
let days=$derived(new Date(Date.UTC(month.getUTCFullYear(),month.getUTCMonth()+1,0)).getUTCDate());
let offset=$derived((month.getUTCDay()+6)%7);
let experience=$derived(config.experiences.find(item=>item.id===experienceId)!);
let flight=$derived(experience?.kind==='flight');
let summary=$derived(formatInquiry(inquiry,config,locale));
let reviewOpen=$derived(reviewed!==''&&reviewed===JSON.stringify(inquiry));
const ui=(es:string,en:string)=>locale==='es'?es:en;
function moveMonth(delta:number){month=new Date(Date.UTC(month.getUTCFullYear(),month.getUTCMonth()+delta,1,12));}
async function review(event:SubmitEvent){event.preventDefault(); if(!special){inquiry.occasion='';inquiry.notes='';} errors=validateInquiry(inquiry,config,new Date(),locale);feedback='';if(Object.keys(errors).length)return;reviewed=JSON.stringify(inquiry);await tick();summaryElement?.focus();summaryElement?.scrollIntoView({behavior:'smooth',block:'nearest'});}
async function copySummary(){try{await navigator.clipboard.writeText(summary);feedback=ui('Solicitud copiada.','Inquiry copied.');}catch{feedback=ui('Selecciona y copia el texto de la solicitud.','Select and copy the inquiry text.');}}
async function save(){await store.saveInquiry(inquiry);}
function saveDraft(){store.saveGuestDraft(inquiry);feedback=store.error?'':store.message;}
</script>
<section id={flight?'solicitar':'reservar'} class="section wrap booking-section svelte-l71das" class:compact aria-labelledby="booking-title">
  <div class="booking-intro svelte-l71das"><p class="eyebrow">{flight?ui('TU EXPERIENCIA, EN UNOS PASOS','YOUR EXPERIENCE, IN A FEW STEPS'):ui('EXPERIENCIA PRIVADA / LA MARQUESA','PRIVATE EXPERIENCE / LA MARQUESA')}</p><h2 id="booking-title" class="svelte-l71das">{flight?ui('Primero, confirmemos tu vuelo.','First, let’s confirm your flight.'):ui('Consulta disponibilidad.','Check availability.')}</h2><p>{flight?ui('Elige tu fecha y cuéntanos cuántas personas viajarán. APEX te confirmará la disponibilidad y la tarifa por persona.','Choose your date and tell us how many people will travel. APEX will confirm availability and the per-person price.'):ui('Un programa definido, las tres actividades incluidas y una salida privada para tu grupo. Elige la fecha y el número de personas para consultar disponibilidad.','A defined program, all three activities included and a private outing for your group. Choose a date and group size to inquire about availability.')}</p>{#if !flight}<ul class="booking-activities svelte-l71das">{#each experience.activities as activity}<li>{activity[locale]}</li>{/each}</ul><p>{ui('Desde','From')} {formatUSD(config.prices[2],locale)} {ui('para dos personas. El total se ajusta al tamaño del grupo. Solicita con al menos 2 días de anticipación; sujeto a disponibilidad.','for two people. The total adjusts to your group size. Inquire at least 2 days ahead; subject to availability.')}</p><details class="price-details svelte-l71das"><summary class="svelte-l71das">{ui('Ver tarifas por grupo (USD)','View group prices (USD)')}</summary><ul>{#each Object.entries(config.prices) as [people,price]}<li>{people} {ui('personas','people')} — {formatUSD(price,locale)}</li>{/each}</ul><p class="small">{ui('Importes totales por grupo, no por persona. Moneda de la tarifa: dólares estadounidenses (USD). APEX confirma el total, la moneda y el medio de pago en la cotización; aquí no se procesa un cobro.','Totals are per group, not per person. Prices are in US dollars (USD). APEX confirms the total, currency and payment method in the quote; this page does not process a charge.')}</p></details>{/if}<ol class="booking-steps"><li>{ui('Prepara y envía tu consulta por WhatsApp.','Prepare and send your inquiry through WhatsApp.')}</li><li>{ui('APEX revisa disponibilidad, recogida, regreso y cotización.','APEX reviews availability, pickup, return and quotation.')}</li><li>{ui('Acuerda las condiciones y el pago con el equipo. La reserva requiere confirmación expresa de APEX.','Agree on terms and payment with the team. A reservation requires explicit confirmation from APEX.')}</li></ol></div>
  <form class="booking-form brand-panel svelte-l71das" onsubmit={review} novalidate>
    <div class="form-row svelte-l71das"><div><p id="date-label">{flight?ui('Fecha solicitada','Requested date'):ui('Fecha de la experiencia','Experience date')}</p>{#if flight}<input type="date" aria-labelledby="date-label" min={today} bind:value={inquiry.date} required aria-invalid={!!errors.date}/>{:else}<div class="calendar svelte-x2s5hc" role="group" aria-labelledby="date-label"><div class="month-nav svelte-x2s5hc"><button type="button" disabled={monthKey<=today.slice(0,7)} class="svelte-x2s5hc" aria-label={ui('Mes anterior','Previous month')} onclick={()=>moveMonth(-1)}>←</button><strong class="svelte-x2s5hc" aria-live="polite">{monthLabel}</strong><button type="button" class="svelte-x2s5hc" aria-label={ui('Mes siguiente','Next month')} onclick={()=>moveMonth(1)}>→</button></div><div class="days svelte-x2s5hc">{#each (locale==='es'?['L','M','X','J','V','S','D']:['M','T','W','T','F','S','S']) as day}<span class="svelte-x2s5hc" aria-hidden="true">{day}</span>{/each}{#each Array(offset) as _}<span class="svelte-x2s5hc"></span>{/each}{#each Array(days) as _,i}{@const date=`${monthKey}-${String(i+1).padStart(2,'0')}`}<button type="button" class="svelte-x2s5hc" class:selected={inquiry.date===date} disabled={!availableDate(date)} aria-label={date} aria-pressed={inquiry.date===date} onclick={()=>inquiry.date=date}>{i+1}</button>{/each}</div><p class="svelte-x2s5hc" aria-live="polite">{inquiry.date||ui('Selecciona una fecha','Select a date')}</p><small class="svelte-x2s5hc">{ui('Jueves a domingo · mínimo 2 días de anticipación','Thursday–Sunday · at least 2 days ahead')}</small></div>{/if}{#if errors.date}<p class="form-error" role="alert">{errors.date}</p>{/if}</div><label for="booking-people">{flight?ui('Número de pasajeros','Number of passengers'):ui('Personas','People')}<input id="booking-people" type="number" min={flight?1:2} max={flight?99:6} step="1" bind:value={inquiry.people} required aria-invalid={!!errors.people}/>{#if errors.people}<span class="form-error" role="alert">{errors.people}</span>{/if}</label></div>
    <label for="inquiry-language">{ui('Idioma del tour','Tour language')}<select id="inquiry-language" bind:value={inquiry.language}><option value="es">Español</option><option value="en">English</option></select></label>
    <details class="pickup-request svelte-l71das"><summary class="svelte-l71das">{ui('Solicitar recogida y regreso (opcional)','Request pickup and return (optional)')}</summary><label for="inquiry-pickup" class="svelte-l71das">{ui('Punto de recogida solicitado','Requested pickup point')}<input id="inquiry-pickup" bind:value={inquiry.pickup} maxlength="300"/></label><label for="inquiry-dropoff" class="svelte-l71das">{ui('Regreso, si es distinto','Return, if different')}<input id="inquiry-dropoff" bind:value={inquiry.dropoff} maxlength="300"/></label><p class="small">{ui('La cobertura, el punto exacto y el costo del transporte se confirman en la cotización. Si dejas el regreso vacío, solicitaremos el mismo punto de recogida; no es una aceptación automática.','Coverage, exact location and transport cost are confirmed in the quote. If you leave return blank, we will request the same pickup point; this is not automatic acceptance.')}</p></details>
    <fieldset id="special-request" class="special-request svelte-l71das"><legend>{ui('OCASIÓN ESPECIAL','SPECIAL OCCASION')}</legend><p class="svelte-l71das">{ui('¿Hay algo que celebrar? Solicita apoyo para un cumpleaños, aniversario u otra ocasión especial.','Something to celebrate? Request help for a birthday, anniversary or other special occasion.')}</p><label class="switch-row svelte-l71das"><input type="checkbox" bind:checked={special} onchange={()=>{if(special&&!inquiry.occasion)inquiry.occasion='birthday';if(!special){inquiry.occasion='';inquiry.notes='';}}}/>{ui('Quiero solicitar atención para una ocasión especial','I would like to request help for a special occasion')}</label>{#if special}<label for="occasion">{ui('Ocasión','Occasion')}<select id="occasion" bind:value={inquiry.occasion}><option value="birthday">{ui('Cumpleaños','Birthday')}</option><option value="anniversary">{ui('Aniversario','Anniversary')}</option><option value="other">{ui('Otra celebración','Other celebration')}</option></select></label><label for="occasion-notes">{ui('¿Cómo podemos ayudarte? (opcional)','How can we help? (optional)')}<textarea id="occasion-notes" rows="3" maxlength="1500" bind:value={inquiry.notes}></textarea></label>{/if}<p class="small svelte-l71das">{ui('La atención especial está sujeta a confirmación y posible costo adicional. El programa de actividades permanece fijo.','Special arrangements are subject to confirmation and possible additional cost. The activity program remains fixed.')}</p></fieldset>
    {#if errors.experienceId}<p class="form-error" role="alert">{errors.experienceId}</p>{/if}
    <button class="button" type="submit">{ui('Revisar consulta','Review inquiry')} ↗</button><p class="small booking-status svelte-l71das">{ui('Revisa tu solicitud y continúa en WhatsApp para enviarla a APEX. Abrir la conversación no confirma disponibilidad ni reserva; tú decides cuándo enviar el mensaje.','Review your request and continue to WhatsApp to send it to APEX. Opening the conversation does not confirm availability or a reservation; you choose when to send the message.')} <a class="privacy-link svelte-l71das" href={resolve('/privacidad/')}>{ui('Privacidad','Privacy')}</a></p>
    {#if reviewOpen}<div bind:this={summaryElement} tabindex="-1" class="apex-inquiry-preview" role="region" aria-labelledby="inquiry-preview-title"><h3 id="inquiry-preview-title">{ui('Tu solicitud, lista para revisar.','Your inquiry, ready to review.')}</h3><pre>{summary}</pre>{#if store.user}<button class="button outline" type="button" disabled={store.busy} onclick={save}>{store.isDemo?ui('Guardar en cuenta de ejemplo','Save to example account'):ui('Guardar consulta en mi cuenta','Save inquiry to my account')}</button>{:else}<a class="text-link" href={resolve('/cuenta/')}>{ui('Inicia sesión para guardar consultas en tu cuenta','Sign in to save inquiries to your account')} →</a><button type="button" class="link-button" onclick={saveDraft}>{ui('Guardar borrador solo en este navegador','Save draft only in this browser')}</button>{/if}{#if store.user&&store.isDemo}<p class="account-booking-demo">{ui('Modo demostración: guardar crea solo un registro de ejemplo en este navegador. No se envía a APEX ni confirma una reserva.','Demonstration mode: saving creates only a sample record in this browser. It is not sent to APEX and does not confirm a reservation.')}</p>{/if}<div class="apex-inquiry-actions"><a class="button" href={whatsappUrl(config,summary)} target="_blank" rel="noopener noreferrer">{ui('Continuar en WhatsApp','Continue to WhatsApp')} ↗</a><button class="button outline" type="button" onclick={copySummary}>{ui('Copiar solicitud','Copy inquiry')}</button></div><p class="small" role="status">{feedback||store.message||ui('Solicitud preparada · no enviada','Inquiry prepared · not sent')}</p>{#if store.error}<p class="form-error" role="alert">{store.error}</p>{/if}</div>{/if}
  </form>
</section>
